import re, sys

def parse(path):
    results = {}
    cur = None
    for line in open(path, errors='replace'):
        m = re.match(r'^=== (test-\S+\.sh) ===$', line)
        if m:
            cur = m.group(1)
            results[cur] = {'rc': None}
            continue
        m = re.match(r'^RC=(\d+)\s*$', line)
        if m and cur:
            results[cur]['rc'] = int(m.group(1))
    return results

head = parse('/tmp/lv2-r1b-evidence/head-full.log')
base = parse('/tmp/lv2-r1b-evidence/base-full.log')

all_suites = sorted(set(head) | set(base))
regressed = []
for s in all_suites:
    h = head.get(s, {}).get('rc')
    b = base.get(s, {}).get('rc')
    if s in ('test-router-v2-retired-arm.sh',):
        # new file, not in baseline dir originally
        cls = 'new-suite' if b is None else ('fixed-by-this-lane' if b != 0 and h == 0 else 'pre-existing')
    elif b is None:
        cls = 'new-suite'
    elif h == 0 and b != 0:
        cls = 'fixed-by-this-lane'
    elif h != 0 and b == 0:
        cls = 'regressed-by-this-lane'
        regressed.append(s)
    elif h != 0 and b != 0:
        cls = 'pre-existing'
    else:
        cls = 'pre-existing' if h == b else 'other'
    print(f"{s}\thead_rc={h}\tbase_rc={b}\t{cls}")

print()
print("regressed:", regressed)
print("total suites:", len(all_suites))
print("head pass:", sum(1 for s in all_suites if head.get(s,{}).get('rc')==0))
print("head fail:", sum(1 for s in all_suites if head.get(s,{}).get('rc') not in (0,None)))
print("base pass:", sum(1 for s in all_suites if base.get(s,{}).get('rc')==0))
print("base fail:", sum(1 for s in all_suites if base.get(s,{}).get('rc') not in (0,None)))

